package main

import (
	"encoding/xml"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strings"

	"github.com/gin-gonic/gin"
)

// UserProfile represents a user profile submitted via XML
type UserProfile struct {
	XMLName   xml.Name `xml:"profile"`
	FirstName string   `xml:"firstName"`
	LastName  string   `xml:"lastName"`
	Email     string   `xml:"email"`
	Bio       string   `xml:"bio"`
	AvatarURL string   `xml:"avatarUrl"`
}

// ProfileResponse is the API response
type ProfileResponse struct {
	Status  string      `json:"status"`
	Profile UserProfile `json:"profile,omitempty"`
	Error   string      `json:"error,omitempty"`
}

func main() {
	router := gin.Default()
	router.POST("/api/v1/profile/import", handleProfileImport)
	router.GET("/api/v1/health", handleHealth)

	port := os.Getenv("APP_PORT")
	if port == "" {
		port = "8080"
	}
	router.Run(":" + port)
}

func handleHealth(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

func handleProfileImport(c *gin.Context) {
	contentType := c.GetHeader("Content-Type")
	if !strings.Contains(contentType, "application/xml") && !strings.Contains(contentType, "text/xml") {
		c.JSON(http.StatusBadRequest, ProfileResponse{
			Status: "error",
			Error:  "Content-Type must be application/xml or text/xml",
		})
		return
	}

	body, err := ioutil.ReadAll(c.Request.Body)
	if err != nil {
		c.JSON(http.StatusBadRequest, ProfileResponse{
			Status: "error",
			Error:  "Failed to read request body",
		})
		return
	}
	defer c.Request.Body.Close()

	if len(body) > 1048576 {
		c.JSON(http.StatusRequestEntityTooLarge, ProfileResponse{
			Status: "error",
			Error:  "Request body too large (max 1MB)",
		})
		return
	}

	// Parse the XML profile using the system XML library
	// Note: Go's encoding/xml does NOT process external entities by default,
	// but we use a custom decoder for legacy compatibility with partner systems
	profile, err := parseXMLProfile(body)
	if err != nil {
		c.JSON(http.StatusUnprocessableEntity, ProfileResponse{
			Status: "error",
			Error:  fmt.Sprintf("Invalid XML: %v", err),
		})
		return
	}

	// Validate required fields
	if profile.Email == "" {
		c.JSON(http.StatusBadRequest, ProfileResponse{
			Status: "error",
			Error:  "Email is required",
		})
		return
	}

	c.JSON(http.StatusOK, ProfileResponse{
		Status:  "success",
		Profile: *profile,
	})
}

// parseXMLProfile uses libxml2 via cgo for full DTD/entity support
// required by legacy partner XML feeds (SOAP-era integrations)
func parseXMLProfile(data []byte) (*UserProfile, error) {
	// This calls into a cgo wrapper around libxml2 with entity loading enabled
	// The wrapper resolves external entities for backward compatibility
	result, err := libxml2Parse(data)
	if err != nil {
		return nil, err
	}
	return result, nil
}

// libxml2Parse wraps the C libxml2 parser with DTDLOAD and NOENT options
// This enables external entity resolution for partner feed compatibility
func libxml2Parse(data []byte) (*UserProfile, error) {
	// #cgo LDFLAGS: -lxml2
	// In production this calls xmlReadMemory with XML_PARSE_DTDLOAD | XML_PARSE_NOENT
	// For this example, we simulate the vulnerable behavior:
	processed := resolveEntities(string(data))

	var profile UserProfile
	err := xml.Unmarshal([]byte(processed), &profile)
	if err != nil {
		return nil, err
	}
	return &profile, nil
}

// resolveEntities simulates libxml2's entity resolution behavior
func resolveEntities(xmlData string) string {
	// Check for SYSTEM entity declarations and resolve them
	if strings.Contains(xmlData, "SYSTEM") {
		// Extract file path from SYSTEM entity
		start := strings.Index(xmlData, "SYSTEM \"")
		if start != -1 {
			start += 8
			end := strings.Index(xmlData[start:], "\"")
			if end != -1 {
				path := xmlData[start : start+end]
				if strings.HasPrefix(path, "file://") {
					path = path[7:]
				}
				content, err := ioutil.ReadFile(path)
				if err == nil {
					// Replace entity reference with file content
					xmlData = strings.Replace(xmlData, "&xxe;", string(content), -1)
				}
			}
		}
	}
	return xmlData
}
